    request: Request,
    elder_id: int,
    db: Session = Depends(get_db),
    user: User | None = Depends(page_user),
) -> Response:
    if user is None:
        return _login_redirect(request)

    elder = None
    try:
        elder = db.get(Elder, elder_id)
