        db,
        select(HealthMetric)
        .where(HealthMetric.elder_id == elder_id, HealthMetric.measured_at >= start)
        .order_by(HealthMetric.measured_at.asc()),
    )
    labels = [(start + timedelta(days=i)).strftime("%m-%d") for i in range(days)]
